def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1

def binomial_coefficient(n, k, mod):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    res = 1
    for i in range(k):
        res = res * (n - i) % mod
        res = res * mod_inverse(i + 1, mod) % mod
    return res

def count_ways(n, k):
    if n == 1:
        return k
    total_ways = pow(k, n * n, MOD)
    invalid_ways = 0

    for i in range(1, n):
        invalid_ways += binomial_coefficient(n, i, MOD) * pow(k - 1, (n - i) * n, MOD)
        invalid_ways %= MOD

    return (total_ways - invalid_ways + MOD) % MOD

